+function escapeCodePoint(codePoint) {
+  if (codePoint <= 0xff) {
+    return `\\x${codePoint.toString(16).padStart(2, '0')}`;
+  }
+  if (codePoint <= 0xffff) {
+    return `\\u${codePoint.toString(16).padStart(4, '0')}`;
+  }
+  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
+}
+
+export function pythonStringRepr(value) {
+  const quote = chooseQuote(value);
+  let result = quote;
+
+  for (const character of value) {
+    const codePoint = character.codePointAt(0);
+
+    if (character === '\\') {
+      result += '\\\\';
+    } else if (character === '\n') {
+      result += '\\n';
+    } else if (character === '\r') {
+      result += '\\r';
+    } else if (character === '\t') {
+      result += '\\t';
+    } else if (character === '\b') {
+      result += '\\b';
+    } else if (character === '\f') {
+      result += '\\f';
+    } else if (character === quote) {
+      result += `\\${quote}`;
+    } else if ((codePoint >= 0x00 && codePoint < 0x20) || (codePoint >= 0x7f && codePoint <= 0x9f)) {
+      result += escapeCodePoint(codePoint);
+    } else {
+      result += character;
+    }
+  }
+
+  result += quote;
+  return result;
+}
+
+export function pythonRepr(value) {
+  if (typeof value === 'string') {
+    return pythonStringRepr(value);
+  }
+
+  if (typeof value === 'number') {
+    if (!Number.isFinite(value)) {
+      throw new TypeError('Only finite numbers are supported.');
