import { jsonStringify } from './json_stringify.mjs';

const DELTA_PAYLOAD = Symbol('deltaPayload');

function diffPath(key) {
  const escapedKey = String(key).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
  return `root['${escapedKey}']`;
}

function isChanged(previousValue, nextValue) {
  return !Object.is(previousValue, nextValue);
}

export function DeepDiff(previousObject, nextObject) {
  const diff = {};
  const deltaPayload = {};

  const addedItems = [];
  const addedDelta = {};

  for (const key of Object.keys(nextObject)) {
    if (!Object.prototype.hasOwnProperty.call(previousObject, key)) {
      const path = diffPath(key);
      addedItems.push(path);
      addedDelta[path] = nextObject[key];
    }
  }

  if (addedItems.length > 0) {
    diff.dictionary_item_added = addedItems;
    deltaPayload.dictionary_item_added = addedDelta;
  }

  const valuesChanged = {};
  const deltaValuesChanged = {};

  for (const key of Object.keys(previousObject)) {
    if (!Object.prototype.hasOwnProperty.call(nextObject, key)) {
      continue;
    }

    if (!isChanged(previousObject[key], nextObject[key])) {
      continue;
    }

    const path = diffPath(key);
    valuesChanged[path] = {
      new_value: nextObject[key],
      old_value: previousObject[key],
    };
    deltaValuesChanged[path] = {
      new_value: nextObject[key],
    };
  }

  if (Object.keys(valuesChanged).length > 0) {
    diff.values_changed = valuesChanged;
    deltaPayload.values_changed = deltaValuesChanged;
  }

  Object.defineProperty(diff, DELTA_PAYLOAD, {
    value: deltaPayload,
    enumerable: false,
  });

  return diff;
}

function getDeltaPayload(diff) {
  return diff[DELTA_PAYLOAD] ?? {};
}

export class Delta {
  constructor(diff) {
    this.payload = getDeltaPayload(diff);
  }

  toString() {
    return `<Delta: ${jsonStringify(this.payload)}>`;
  }
}

