  }

  if (value === null) {
    return 'None';
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => pythonRepr(item)).join(', ')}]`;
  }

  if (typeof value === 'object') {
    const entries = Object.keys(value).map((key) => `${pythonStringRepr(key)}: ${pythonRepr(value[key])}`);
