const OPTION_SPECS = [
  { flag: '--a', dest: 'a', metavar: 'A', type: 'string' },
  { flag: '--b', dest: 'b', metavar: 'B', type: 'int' },
  { flag: '--c', dest: 'c', metavar: 'C', type: 'int' },
];

const OPTION_BY_FLAG = Object.fromEntries(
  OPTION_SPECS.map((spec) => [spec.flag, spec]),
);

export function getProgramName(scriptPath = '') {
  if (!scriptPath) {
    return 'test15.mjs';
  }

  const normalized = scriptPath.replace(/\\/g, '/');
  const parts = normalized.split('/');
  return parts[parts.length - 1] || 'test15.mjs';
}

export function formatUsage(scriptName) {
  return `usage: ${scriptName} [-h] --a A --b B --c C`;
}

export function formatHelp(scriptName) {
  return `${formatUsage(scriptName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C\n`;
}

export function parseTest15Args(
  argv,
  {
    scriptName = 'test15.mjs',
    stdout = process.stdout,
    stderr = process.stderr,
    exit = (code) => process.exit(code),
  } = {},
) {
  if (argv.includes('-h') || argv.includes('--help')) {
    stdout.write(formatHelp(scriptName));
    exit(0);
    return null;
  }

  const values = {};
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (!token.startsWith('-')) {
      extras.push(token);
      continue;
    }

    const { flag, inlineValue } = splitOptionToken(token);
    const spec = OPTION_BY_FLAG[flag];

    if (!spec) {
      extras.push(token);
      continue;
    }

    let rawValue = inlineValue;

    if (rawValue === null) {
      const nextToken = argv[index + 1];

      if (nextToken === undefined || looksLikeAnotherOption(nextToken)) {
        failWithUsage(
          scriptName,
          stderr,
          exit,
          `argument ${spec.flag}: expected one argument`,
        );
        return null;
      }

      rawValue = nextToken;
      index += 1;
    }

    const parsedValue = parseOptionValue(spec, rawValue);

    if (!parsedValue.ok) {
      failWithUsage(
        scriptName,
        stderr,
        exit,
        `argument ${spec.flag}: invalid int value: ${quoteErrorValue(rawValue)}`,
      );
      return null;
    }

    values[spec.dest] = parsedValue.value;
  }

  const missingFlags = OPTION_SPECS
    .filter((spec) => !Object.prototype.hasOwnProperty.call(values, spec.dest))
    .map((spec) => spec.flag);

  if (missingFlags.length > 0) {
    failWithUsage(
      scriptName,
      stderr,
      exit,
      `the following arguments are required: ${missingFlags.join(', ')}`,
    );
    return null;
  }

  if (extras.length > 0) {
    failWithUsage(
      scriptName,
      stderr,
      exit,
      `unrecognized arguments: ${extras.join(' ')}`,
    );
    return null;
  }

  return values;
}

function splitOptionToken(token) {
  const equalsIndex = token.indexOf('=');

  if (equalsIndex > 1) {
    return {
      flag: token.slice(0, equalsIndex),
      inlineValue: token.slice(equalsIndex + 1),
    };
  }

  return { flag: token, inlineValue: null };
}

function looksLikeAnotherOption(token) {
  if (token === '-') {
    return false;
  }

  if (/^-\d+(?:_\d+)*$/.test(token)) {
    return false;
  }

  return token.startsWith('-');
}

function parseOptionValue(spec, rawValue) {
  if (spec.type === 'string') {
    return { ok: true, value: rawValue };
  }

  return parsePythonInt(rawValue);
}

export function parsePythonInt(rawValue) {
  const trimmed = rawValue.trim();

  if (!/^[+-]?(?:\d+(?:_\d+)*)$/.test(trimmed)) {
    return { ok: false };
  }

  try {
    return { ok: true, value: BigInt(trimmed.replace(/_/g, '')) };
  } catch {
    return { ok: false };
  }
}

function failWithUsage(scriptName, stderr, exit, message) {
  stderr.write(`${formatUsage(scriptName)}\n${scriptName}: error: ${message}\n`);
  exit(2);
}

function quoteErrorValue(rawValue) {
  return `'${rawValue.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

