import {
  formatDeepDiff,
  formatDelta,
  isDiffResult,
  isDelta,
} from '../deepdiff/index.mjs';
import { pythonRepr } from '../format/python_repr.mjs';

export function formatPrintedValue(value) {
  if (isDiffResult(value)) {
    return formatDeepDiff(value);
  }

  if (isDelta(value)) {
    return formatDelta(value);
  }

  return pythonRepr(value);
}

export function printValue(value, stdout = process.stdout) {
  stdout.write(`${formatPrintedValue(value)}\n`);
}

